import six
from abc import abstractproperty, ABCMeta


@six.add_metaclass(ABCMeta)
class HexParser(object):

    @abstractproperty
    def get_converted_msgs_list(self, file_or_string):
        """Returns list of Message objects for finite source (file or string)"""
        pass

    @abstractproperty
    def get_unparsed_msgs_list(self, file_or_string):
        """
        Returns list of data records (named tuples with at least .hex and .type attributes)
        objects for finite source (file or string).
        """
        pass

    @abstractproperty
    def iter_unparsed_msg(self, source):
        """
        Returns generator used to iter over infinite source (e.g. output of process).
        :param source: either string or file-like objects implementing read(size)
        """
        pass

    @abstractproperty
    def iter_parsed_msg(self, source):
        """
        Returns generator used to iter over infinite source (e.g. output of process).
        :param source: either string or file-like objects implementing read(size)
        """
        pass
